const express = require('express');
require('reflect-metadata');
const { plainToInstance } = require('class-transformer');
const { validateOrReject, IsUUID, IsUrl, IsArray, IsString } = require('class-validator');
const knex = require('knex')({ client: 'pg', connection: process.env.DB_URL });

const app = express();
app.use(express.json());

class RegisterWebhookDto {
  @IsUUID()
  workspaceId;

  @IsUrl()
  callbackUrl;

  @IsArray()
  @IsString({ each: true })
  subscribedEvents;
}

const validateBody = (Cls) => async (req, res, next) => {
  const instance = plainToInstance(Cls, req.body);
  try {
    await validateOrReject(instance);
    req.dto = instance;
    next();
  } catch (err) {
    res.status(422).json({ error: 'Unprocessable entity', details: err });
  }
};

app.post('/api/developer/webhooks', validateBody(RegisterWebhookDto), async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { workspaceId, callbackUrl, subscribedEvents } = req.dto;

  // Verify caller has admin permission on the workspace
  const adminMembership = await knex('workspace_members')
    .where({ workspace_id: workspaceId, user_id: req.user.id, role: 'WORKSPACE_ADMIN' })
    .first();

  if (!adminMembership) {
    return res.status(403).json({ error: 'Forbidden: admin permissions required for target workspace' });
  }

  const [created] = await knex('workspace_webhooks')
    .insert({
      workspace_id: workspaceId,
      callback_url: callbackUrl,
      subscribed_events: JSON.stringify(subscribedEvents),
      created_by: req.user.id,
      created_at: new Date()
    })
    .returning(['id', 'workspace_id', 'callback_url']);

  res.status(201).json({ webhook: created });
});

app.listen(7004);
